{
  "passageId": "surface-tension-laplace",
  "items": [
    {
      "id": "R1",
      "type": "CAUSE",
      "otherName": "",
      "reason": "분자 간 인력으로 생긴 표면 장력이 방울의 구형 형성을 실제로 일으키는 인과적 연결이다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "표면 장력의 작용과 그로 인해 방울이 구형을 취하는 현상을 연결하므로 실제 작용에 해당한다."
    },
    {
      "id": "R3",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "방울에 작용하는 방향이라는 같은 기준에서 내부 압력은 팽창, 외부 압력과 표면 장력은 수축으로 대비된다."
    },
    {
      "id": "R4",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "방울에 작용하는 압력들의 관계를 라플라스 식과 비례 관계로 표현하므로 식을 통한 뜻풀이에 해당한다."
    },
    {
      "id": "R5",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "내외부 압력 차이와의 관계를 기준으로 표면 장력의 정비례와 반지름의 반비례가 대비된다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "공기가 고압에서 저압으로 이동한다는 원리를 폐포의 공기 출입을 설명하는 근거로 제시한다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "계면 활성제의 분비가 액체층의 표면 장력 감소로 이어지는 실제 작용을 나타낸다."
    },
    {
      "id": "R8",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "폐포를 수축시키는 표면 장력에 대응하여 이를 낮추는 계면 활성제의 작용이 제시된다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "계면 활성제에 의한 표면 장력 감소가 폐포의 확장을 쉽게 만드는 실제 인과 관계이다."
    },
    {
      "id": "R10",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 설명한 라플라스 식을 폐포의 압력과 표면 장력이라는 다른 현상에 적용한다."
    },
    {
      "id": "R11",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "액체 방울에서 설명한 표면 장력의 수축 작용을 폐포를 둘러싼 액체층에 가져다 쓴다."
    },
    {
      "id": "R12",
      "type": "CAUSE",
      "otherName": "",
      "reason": "두 기포 사이의 공기 이동이 더 큰 기포 하나의 형성을 일으킨다고 명시한다."
    },
    {
      "id": "R13",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "라플라스 식을 크기가 다른 두 기포의 합쳐짐이라는 별도의 현상을 이해하는 데 적용한다."
    },
    {
      "id": "R14",
      "type": "PROCESS",
      "otherName": "",
      "reason": "노즐에서 잉크가 분사된 다음 공기 중에서 방울이 되는 단계의 순서를 제시한다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "공기 중에서 잉크 방울이 형성된 다음 종이에 도달하는 진행 순서를 나타낸다."
    },
    {
      "id": "R16",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 세운 라플라스 식을 구형 잉크 방울에 적용하여 내외부 압력의 관계를 설명한다."
    },
    {
      "id": "R17",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "구형 잉크 방울이 형성되더라도 그것만으로 제대로 된 인쇄까지 보장되지는 않는다는 한계를 제시한다."
    },
    {
      "id": "R18",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "잉크 방울의 형성만으로는 부족하다는 지적에서 안정적 도착 정도를 나타내는 지표로 논의를 옮긴다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "오네소르게 수의 결정 요인들을 제시한 뒤 그중 점도의 의미를 세부적으로 설명한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "네 요인에 의해 결정된다는 포괄적 설명을 점도 증가에 따른 수치 변화로 구체화한다."
    },
    {
      "id": "R21",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "결정 요인에 대한 설명을 표면 장력·밀도·노즐 지름의 곱과 오네소르게 수의 구체적 관계로 풀어 준다."
    },
    {
      "id": "R22",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "오네소르게 수에 미치는 영향이라는 기준에서 점도의 증가는 수치를 높이고 나머지 세 값의 곱의 증가는 수치를 낮춘다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "네 요인과 오네소르게 수의 관계를 근거로 요인 조절을 통해 안정적인 인쇄가 가능하다는 결론을 도출한다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "안정적인 인쇄가 가능하도록 조절한다는 설명을 오네소르게 수 0.1에서 1.0이라는 수치 범위로 구체화한다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "점도가 클수록 오네소르게 수가 커진다는 관계를 점도가 커서 안정 범위를 넘는 구체적 사례로 보여 준다."
    },
    {
      "id": "R26",
      "type": "CONDITION",
      "otherName": "",
      "reason": "오네소르게 수가 안정 범위 안에 있는 경우와 그보다 큰 경우에 따라 인쇄 결과가 갈린다."
    },
    {
      "id": "R27",
      "type": "CONDITION",
      "otherName": "",
      "reason": "오네소르게 수가 안정 범위보다 큰지 작은지에 따라 미분사와 위성 방울 발생으로 결과가 분기된다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "수많은 위성 잉크 방울의 발생이 원치 않는 오염을 실제로 일으킨다."
    },
    {
      "id": "R29",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "오네소르게 수가 동일한 네 요인에 의해 결정된다는 내용을 마지막 문장에서 그대로 재진술한다."
    },
    {
      "id": "R30",
      "type": "PROCESS",
      "otherName": "",
      "reason": "네 요인으로 오네소르게 수를 결정한 뒤 그 산출값을 바탕으로 인쇄 안정성을 파악하는 다음 단계가 진행된다."
    },
    {
      "id": "R31",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "오네소르게 수의 범위별 인쇄 결과가 그 수치로 인쇄 안정성을 판단할 수 있다는 결론을 뒷받침한다."
    }
  ]
}

